def execute(arguments):
    """
    创建目录

    参数:
        arguments (dict): 包含以下字段
            - path (str): 目录路径，必填

    返回:
        dict: 包含创建结果的字典
            - success (bool): 是否成功
            - path (str): 创建的目录路径
            - created (bool): 是否创建成功
            - error (str): 错误信息（失败时）
    """
    import os

    path = arguments.get("path", "")

    if not path:
        return {"success": False, "error": "请提供目录路径"}

    try:
        os.makedirs(path, exist_ok=True)

        return {
            "success": True,
            "path": path,
            "created": True
        }
    except Exception as e:
        return {"success": False, "error": f"创建目录失败: {str(e)}"}
